/*selectBuyerMdCmGoodsCategList*/
SELECT COD.CODE1 , COD.CODE2 , COD.TEXT1 , COD.TEXT2 , COD.TEXT3 , COD.TEXT4 FROM ICOMCOD3 COD WHERE COD.TYPE =#{st_type} AND COD.BUYER =#{st_com_code} AND COD.FLAG = 'Y'
AND COD.CODE1 = #{st_user_id}
AND UPPER(TEXT1) LIKE UPPER( '%' || #{st_mycateg} || '%')
ORDER BY COD.TEXT1

mapper.update:
/*insertBuyerMdCmGoodsCateg*/

		INSERT INTO ICOMCOD3 /* 회사별 코드관리 */
		(
		  BUYER
		  , TYPE
		  , CODE1
		  , CODE2
		  , TEXT1
		  , TEXT2			  
		  , TEXT3
		  , TEXT4
		  , FLAG
		  , ADD_USER_ID
		  , ADD_DATE
		)
		VALUES
		(
		    #{st_com_code}
		  , #{st_type}
		  , #{st_user_id}
		  , (SELECT'MC'||TO_CHAR(NVL(MAX(SUBSTR(CODE2,3,5)),0)+1,'FM00000')
				FROM ICOMCOD3 COD
				WHERE  COD.TYPE = #{st_type}
				AND BUYER = #{st_com_code}
				AND CODE1 = #{st_user_id}
				AND CODE2 != 'MCDEFAULT')
		  , #{TEXT1}
		  , #{TEXT2}
		  , #{TEXT3}
		  , #{TEXT4}
		  , 'Y'
		  , #{st_user_id}
		  , TO_CHAR(SYSDATE , 'YYYYMMDD')
		)

/*updateBuyerMdCmGoodsCateg*/

		UPDATE ICOMCOD3 /* 회사별 코드관리 */
		SET TEXT1 = #{TEXT1}
		  , TEXT2 = #{TEXT2}
		  , TEXT3 = #{TEXT3}
		  , TEXT4 = #{TEXT4}
		WHERE 1=1
		AND TYPE  = #{st_type}
		AND BUYER = #{st_com_code}
		AND CODE1  = #{CODE1}
		AND CODE2  = #{CODE2}

/*deleteBuyerMdCmGoodsCateg*/

		DELETE FROM ICOMCOD3 /* 회사별 코드관리 */
		WHERE 1=1
		AND TYPE  = #{st_type}
		AND BUYER = #{st_com_code}
		AND CODE1  = #{CODE1}
		AND CODE2  = #{CODE2}

/*deleteBuyerMdCmGoodsCategItem*/

		DELETE FROM ICOMCART
		WHERE USER_ID = #{CODE1}
		AND BUYER = #{st_com_code}
		AND USE_FLAG ='R'
		AND MY_GROUP = #{CODE2}
